var Q24 = [
{n:1, q:'"El Municipio" es el epígrafe:', o:{a:'Del Título I de la Ley 7/85, Reguladora de las Bases del Régimen Local.',b:'Del Título II de la Ley 7/85, Reguladora de las Bases del Régimen Local.',c:'Del Título III de la Ley 7/85, Reguladora de las Bases del Régimen Local.',d:'Del Título IV de la Ley 7/85, Reguladora de las Bases del Régimen Local.'}, correct:'b', why:{b:'El Título II de la LRBRL (Ley 7/1985) lleva por rúbrica "El Municipio" y regula su organización, competencias y régimen jurídico.'}},
{n:2, q:'En el ámbito de la organización municipal, son órganos colegiados de gobierno:', o:{a:'Aquellos en los que las decisiones se toman de manera personal.',b:'Aquellos en los que las decisiones se adoptan mediante la suma de voluntades de las personas que los integran.',c:'Los citados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Los órganos colegiados son aquellos integrados por varias personas cuyas decisiones se adoptan mediante la suma de voluntades de sus miembros, a diferencia de los unipersonales.'}},
{n:3, q:'La Ley 7/85, Reguladora de las Bases del Régimen Local, dedica el Capítulo II del Título II:', o:{a:'Al territorio y la población municipal.',b:'A los órganos complementarios del municipio.',c:'A lo citado en las respuestas a y b.',d:'A la organización municipal.'}, correct:'d', why:{d:'El Capítulo II del Título II de la LRBRL está dedicado a "La organización municipal", regulando los órganos municipales necesarios y complementarios.'}},
{n:4, q:'Dentro de la organización municipal existen órganos unipersonales y órganos colegiados de gobierno, siendo colegiados:', o:{a:'El Pleno y la Junta de Gobierno Local.',b:'Los Concejales.',c:'Son colegiados los citados en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Pleno, la Junta de Gobierno Local y los Concejales en comisión tienen carácter colegiado al adoptar sus decisiones mediante suma de voluntades.'}},
{n:5, q:'Los órganos colegiados de las entidades locales funcionan en régimen de sesiones:', o:{a:'Públicas o privadas, según lo que disponga la convocatoria.',b:'Ordinarias de periodicidad preestablecida y extraordinarias, que pueden ser, además, urgentes.',c:'Obligatorias o facultativas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Los órganos colegiados de las entidades locales funcionan en sesiones ordinarias (periodicidad preestablecida) y extraordinarias, que pueden ser declaradas urgentes.'}},
{n:6, q:'La organización municipal responde a las reglas establecidas:', o:{a:'En el art.20 de la Ley 7/85, Reguladora de las Bases del Régimen Local.',b:'En el Título III de la Ley 7/85, Reguladora de las Bases del Régimen Local.',c:'En el art.30 de la Ley 7/85, Reguladora de las Bases del Régimen Local.',d:'En el Título I de la Ley 7/85, Reguladora de las Bases del Régimen Local.'}, correct:'a', why:{a:'El art. 20 LRBRL establece las reglas a las que responde la organización municipal, enumerando los órganos necesarios del municipio.'}},
{n:7, q:'Dentro de la organización municipal, el Pleno es un órgano colegiado que existirá:', o:{a:'En municipios con población inferior a 5.000 habitantes, cuando así lo autorice la Comunidad Autónoma respectiva.',b:'En municipios con población inferior a 5.000 habitantes, a instancia de la Diputación Provincial respectiva.',c:'En los municipios citados en las respuestas a y b.',d:'En todos los Ayuntamientos.'}, correct:'d', why:{d:'El art. 20 LRBRL establece que el Pleno es un órgano necesario que existirá en todos los Ayuntamientos sin excepción.'}},
{n:8, q:'Según el art.22.1. de la Ley 7/85, Reguladora de las Bases del Régimen Local:', o:{a:'El Alcalde puede delegar la convocatoria del Pleno en uno de los concejales.',b:'El Pleno, integrado por todos los Concejales, es presidido por el Alcalde.',c:'El Alcalde puede delegar la presidencia del Pleno en uno de los concejales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 22.1 LRBRL establece que el Pleno, presidido por el Alcalde e integrado por todos los Concejales, puede ver delegada su convocatoria en uno de los concejales por el Alcalde.'}},
{n:9, q:'El art.22.2 de la Ley 7/85, Reguladora de las Bases del Régimen Local, establece las atribuciones que corresponden, en todo caso:', o:{a:'Al Pleno municipal en los ayuntamientos y a la Asamblea vecinal en el régimen de Concejo Abierto.',b:'A la Junta de Gobierno del ayuntamiento.',c:'Al Alcalde y a los Concejales.',d:'A todos los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 22.2 LRBRL enumera las atribuciones que corresponden en todo caso al Pleno municipal en los Ayuntamientos y a la Asamblea vecinal en el régimen de Concejo Abierto.'}},
{n:10, q:'El control y la fiscalización de los órganos de gobierno municipales es una competencia atribuida, en todo caso:', o:{a:'A la Junta de Gobierno del ayuntamiento, donde existiere.',b:'Al Pleno municipal en los Ayuntamientos y a la Asamblea vecinal en el régimen de Concejo Abierto.',c:'Al Alcalde.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 22.2.a) LRBRL atribuye al Pleno, en todo caso, el control y la fiscalización de los órganos de gobierno municipales.'}},
{n:11, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'La aprobación del reglamento orgánico y de las ordenanzas.',b:'Dirigir el gobierno y la administración municipal.',c:'Dirigir, inspeccionar e impulsar los servicios y obras municipales.',d:'Todo lo citado en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 22.2.d) LRBRL atribuye al Pleno, en todo caso, la aprobación del reglamento orgánico y de las ordenanzas.'}},
{n:12, q:'No es competencia del Ayuntamiento Pleno:', o:{a:'La votación de la moción de censura al Alcalde.',b:'Aprobar el Reglamento Orgánico.',c:'Ejercitar acciones judiciales, extrajudiciales y administrativas sobre materias de competencia plenaria, en caso de urgencia.',d:'El control y fiscalización de los órganos de gobierno municipales.'}, correct:'c', why:{c:'El ejercicio de acciones judiciales y extrajudiciales en casos de urgencia puede corresponder al Alcalde, no al Pleno. El art. 22.2 LRBRL no incluye esta función entre las atribuciones plenarias indelegables.'}},
{n:13, q:'Los acuerdos relativos a la participación en organizaciones supramunicipales debe aprobarlos, en todo caso:', o:{a:'El Alcalde.',b:'El Pleno municipal en el ayuntamiento o la Asamblea vecinal en el régimen de Concejo Abierto.',c:'La Junta de Gobierno Local, donde existiere.',d:'Quien determine el Reglamento Orgánico del ente de que se trate.'}, correct:'d', why:{d:'Los acuerdos sobre participación en organizaciones supramunicipales son aprobados por quien determine el Reglamento Orgánico del ente de que se trate, según la LRBRL.'}},
{n:14, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'Aprobar los acuerdos relativos a alteración del término municipal.',b:'Dirigir el gobierno y la administración municipal.',c:'Dirigir, inspeccionar e impulsar los servicios y obras municipales.',d:'Todo lo citado en las respuestas anteriores.'}, correct:'a', why:{a:'El art. 22.2.b) LRBRL atribuye al Pleno, en todo caso, la aprobación de los acuerdos relativos a la alteración del término municipal.'}},
{n:15, q:'La aprobación de los acuerdos relativos a la creación o supresión de municipios, es competencia atribuida, en todo caso:', o:{a:'A la Comisión especial creada al efecto.',b:'A la Junta de Gobierno Local, si estuviera constituida.',c:'Al Pleno municipal en el ayuntamiento o a la Asamblea vecinal en el régimen de Concejo Abierto.',d:'A quien determine el Reglamento Orgánico del ente de que se trate.'}, correct:'c', why:{c:'El art. 22.2.b) LRBRL atribuye al Pleno, en todo caso, la aprobación de los acuerdos relativos a la creación o supresión de municipios.'}},
{n:16, q:'La creación de órganos desconcentrados, la alteración de la capitalidad del municipio y el cambio de nombre de éste, es competencia, en todo caso:', o:{a:'A la Comisión especial creada al efecto.',b:'Al Pleno municipal en el ayuntamiento o a la Asamblea vecinal en el régimen de Concejo Abierto.',c:'A la Junta de Gobierno Local, si estuviera constituida.',d:'A quien determine el Reglamento Orgánico del ente de que se trate.'}, correct:'b', why:{b:'El art. 22.2.b) LRBRL atribuye al Pleno, en todo caso, las decisiones sobre creación de órganos desconcentrados, alteración de capitalidad y cambio de nombre del municipio.'}},
{n:17, q:'En un Ayuntamiento, los acuerdos relativos a la adopción o modificación de su bandera, enseña o escudo deben ser aprobados, en todo caso, por:', o:{a:'El Pleno.',b:'El Alcalde.',c:'La Comisión Especial de Sugerencias y Reclamaciones.',d:'La Junta de Gobierno Local.'}, correct:'a', why:{a:'El art. 22.2.b) LRBRL atribuye al Pleno, en todo caso, la aprobación de los acuerdos relativos a la adopción o modificación de la bandera, enseña o escudo municipal.'}},
{n:18, q:'En el régimen de Concejo Abierto, los acuerdos relativos a la adopción o modificación de su bandera, enseña o escudo deben ser aprobados, en todo caso, por:', o:{a:'El Alcalde.',b:'La Comisión Especial de Sugerencias y Reclamaciones.',c:'La Asamblea Vecinal.',d:'El Pleno.'}, correct:'c', why:{c:'En el régimen de Concejo Abierto, la Asamblea Vecinal asume las competencias que en el régimen ordinario corresponden al Pleno, incluyendo la modificación de símbolos municipales.'}},
{n:19, q:'La aprobación de la oferta de empleo público es competencia atribuida al Pleno municipal en los Ayuntamientos, y a la Asamblea Vecinal en el régimen de Concejo Abierto.', o:{a:'Sí, en todo caso.',b:'Solo en municipios de gran población.',c:'Solo en municipios que no sean de gran población.',d:'No. En ningún caso.'}, correct:'d', why:{d:'La aprobación de la oferta de empleo público no figura entre las competencias indelegables del Pleno en el art. 22.2 LRBRL para todos los municipios.'}},
{n:20, q:'La aprobación inicial del planeamiento general y la aprobación que ponga fin a la tramitación municipal de los planes previstos en la legislación urbanística, es una competencia atribuida, en todo caso:', o:{a:'A la Junta de Gobierno Local, si estuviera constituida.',b:'Al Pleno municipal en el ayuntamiento o a la Asamblea vecinal en el régimen de Concejo Abierto.',c:'A quien determine el Reglamento Orgánico del ente de que se trate.',d:'Al Alcalde.'}, correct:'b', why:{b:'El art. 22.2.c) LRBRL atribuye al Pleno, en todo caso, la aprobación inicial del planeamiento general urbanístico y los instrumentos de ordenación territorial.'}},
{n:21, q:'El Ayuntamiento Pleno, con sujeción a las normas reglamentarias que dicte el Estado, tiene competencia:', o:{a:'Para aprobar las bases de las pruebas para la selección del personal.',b:'Para aprobar las bases que hayan de regir en los concursos de provisión de puestos de trabajo.',c:'Para ejercitar acciones judiciales, extrajudiciales y administrativas sobre materias de competencia plenaria, en caso de urgencia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Las opciones a), b) y c) no corresponden exactamente a competencias del Pleno tal como las define el art. 22.2 LRBRL; ninguna de ellas es atribución indelegable del Pleno en los términos descritos.'}},
{n:22, q:'Las cuestiones relativas a compatibilidad o incompatibilidad del personal al servicio de un Ayuntamiento, deben ser aprobadas por:', o:{a:'El Alcalde, como jefe superior de la Corporación.',b:'El Concejal de personal.',c:'El Pleno.',d:'La Junta de Gobierno Local.'}, correct:'c', why:{c:'Las cuestiones de compatibilidad e incompatibilidad del personal al servicio del Ayuntamiento son competencia del Pleno conforme a la LRBRL.'}},
{n:23, q:'En un Ayuntamiento, la separación del servicio de sus funcionarios corresponde:', o:{a:'Al Pleno.',b:'Al Alcalde.',c:'A la Junta de Gobierno Local en municipios de gran población y al Alcalde en los municipios que no son de gran población.',d:'A la Junta de Gobierno Local en municipios que no son de gran población y al Alcalde en los municipios de gran población.'}, correct:'c', why:{c:'En municipios de gran población la separación del servicio corresponde a la Junta de Gobierno Local; en los de régimen común, al Alcalde, conforme a la LRBRL.'}},
{n:24, q:'En un Ayuntamiento, el despido del personal laboral es competencia:', o:{a:'De la Junta de Gobierno Local en municipios de gran población y del Alcalde en los municipios de régimen común.',b:'Del Pleno.',c:'Del Alcalde.',d:'De la Junta de Gobierno Local en municipios de régimen común, y al Alcalde en los municipios de gran población.'}, correct:'a', why:{a:'El despido del personal laboral corresponde a la Junta de Gobierno Local en municipios de gran población y al Alcalde en los de régimen común, según la LRBRL.'}},
{n:25, q:'El Ayuntamiento Pleno ¿tiene competencia para imponer sanciones por faltas graves a los funcionarios con habilitación de carácter estatal que supongan la destitución del cargo o la separación definitiva del servicio?', o:{a:'Sí.',b:'No.',c:'No, porque es competencia del Alcalde.',d:'Sí, siempre que sea a propuesta del Concejal de Personal.'}, correct:'b', why:{b:'La imposición de sanciones por faltas graves a funcionarios con habilitación estatal que supongan destitución o separación definitiva no es competencia del Pleno municipal, sino que se tramita conforme a la normativa del Estado para ese colectivo.'}},
{n:26, q:'No es competencia del Ayuntamiento Pleno...', o:{a:'La determinación de los recursos propios de carácter tributario, y la aprobación y modificación de los presupuestos.',b:'Ordenar gastos y rendir cuentas.',c:'La aprobación y modificación de los Reglamentos Municipales.',d:'La aprobación de la plantilla de personal y de la relación de puestos de trabajo.'}, correct:'b', why:{b:'Ordenar gastos y rendir cuentas es competencia del Alcalde o de la Junta de Gobierno Local, no del Pleno. El art. 22.2 LRBRL no incluye esta función entre las atribuciones del Pleno.'}},
{n:27, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'La aprobación de las formas de gestión de servicios y expedientes de municipalización.',b:'La aceptación de la delegación de competencias hecha por otras administraciones públicas.',c:'Las funciones que expresamente les confieran las leyes.',d:'Todo lo reflejado en las respuestas anteriores les corresponde, en todo caso.'}, correct:'d', why:{d:'El art. 22.2 LRBRL atribuye al Pleno, en todo caso, las formas de gestión de servicios, la aceptación de delegaciones de competencias y las funciones expresamente atribuidas por ley.'}},
{n:28, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'La disposición de gastos en materia de su competencia y la aprobación de las cuentas.',b:'Ordenar gastos y rendir cuentas.',c:'La aprobación de la oferta de empleo público.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'a', why:{a:'La disposición de gastos en materia de su competencia y la aprobación de las cuentas es una atribución del Pleno conforme al art. 22.2 LRBRL.'}},
{n:29, q:'En un Ayuntamiento, el reconocimiento extrajudicial de créditos, siempre que no exista dotación presupuestaria, las operaciones de crédito o concesión de quita y espera, son competencias atribuidas:', o:{a:'Al Pleno.',b:'A la Junta de Gobierno.',c:'A la Comisión Especial de Cuentas.',d:'Al Alcalde.'}, correct:'a', why:{a:'El art. 22.2.f) LRBRL atribuye al Pleno el reconocimiento extrajudicial de créditos sin dotación presupuestaria y las operaciones de crédito relevantes.'}},
{n:30, q:'La alteración de la calificación jurídica de los bienes de dominio público es una competencia atribuida, en todo caso:', o:{a:'A la Junta de Gobierno Local, si estuviera constituida.',b:'Al Pleno municipal en el Ayuntamiento o a la Asamblea Vecinal en el régimen de Concejo Abierto.',c:'A quien determine el Reglamento Orgánico del Organismo de que se trate.',d:'Al Alcalde.'}, correct:'b', why:{b:'El art. 22.2.g) LRBRL atribuye al Pleno, en todo caso, la alteración de la calificación jurídica de los bienes demaniales o comunales.'}},
{n:31, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'Aprobar la oferta de empleo público.',b:'La declaración de lesividad de los actos del Ayuntamiento.',c:'Ordenar gastos y rendir cuentas.',d:'Todo lo reflejado en las respuestas anteriores les corresponde.'}, correct:'b', why:{b:'El art. 22.2.j) LRBRL atribuye al Pleno, en todo caso, la declaración de lesividad de los actos del Ayuntamiento.'}},
{n:32, q:'En un Ayuntamiento, el planteamiento de conflictos de competencias a otras entidades Locales y demás Administraciones públicas, es competencia, en todo caso:', o:{a:'Del Alcalde.',b:'De la Junta de Gobierno Local.',c:'Del Pleno.',d:'De la Comisión especial creada a efecto.'}, correct:'c', why:{c:'El art. 22.2.k) LRBRL atribuye al Pleno, en todo caso, el planteamiento de conflictos de competencias a otras entidades locales y demás Administraciones públicas.'}},
{n:33, q:'En el régimen de Concejo Abierto, el planteamiento de conflictos de competencias a otras entidades Locales y demás Administraciones públicas, es competencia, en todo caso:', o:{a:'Del Alcalde.',b:'De la Comisión Especial de Sugerencias y Reclamaciones.',c:'De la Asamblea Vecinal.',d:'Del Pleno.'}, correct:'c', why:{c:'En el régimen de Concejo Abierto, la Asamblea Vecinal asume las competencias del Pleno, incluido el planteamiento de conflictos de competencias.'}},
{n:34, q:'En municipios de régimen común, distribuir las retribuciones complementarias que no sean fijas ni periódicas es competencia:', o:{a:'Del Pleno.',b:'Del Alcalde.',c:'Del Concejal de Personal.',d:'Todas las respuestas son falsas, ya que tales retribuciones están fijadas en la Ley.'}, correct:'b', why:{b:'En municipios de régimen común, la distribución de retribuciones complementarias no fijas ni periódicas corresponde al Alcalde conforme a la LRBRL.'}},
{n:35, q:'En un Ayuntamiento, la competencia para conceder medallas, emblemas, condecoraciones y otros distintivos honoríficos, corresponde:', o:{a:'Al Alcalde.',b:'A la Junta de Gobierno Local.',c:'Al Pleno.',d:'A la Comisión de servicios protocolarios del Ayuntamiento.'}, correct:'c', why:{c:'La concesión de medallas, emblemas, condecoraciones y otros distintivos honoríficos es una competencia del Pleno del Ayuntamiento.'}},
{n:36, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'La votación de la moción de censura al Alcalde.',b:'La votación de la cuestión de confianza planteada por el alcalde.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 22.3 LRBRL establece que la moción de censura y la cuestión de confianza son en todo caso competencia indelegable del Pleno.'}},
{n:37, q:'Corresponde, en todo caso, al Pleno municipal en los Ayuntamientos, y a la Asamblea vecinal en el régimen de Concejo Abierto:', o:{a:'La fijación de la cuantía de las retribuciones complementarias fijas y periódicas de los funcionarios y el número y régimen del personal eventual.',b:'La votación de la moción de censura al Alcalde y de la cuestión de confianza planteada por éste.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Ninguna de las opciones refleja exactamente las competencias indelegables del Pleno tal como las enuncia el art. 22.2 y 22.3 LRBRL en todos sus términos.'}},
{n:38, q:'Con respecto a la delegación de atribuciones del Pleno:', o:{a:'El Pleno puede delegar el ejercicio de algunas de sus atribuciones en el Alcalde y en la Junta de Gobierno Local.',b:'El Pleno no puede delegar el ejercicio de ninguna de sus atribuciones.',c:'El Pleno solo puede delegar competencias en el Alcalde.',d:'El Pleno solo puede delegar competencias en la Junta de Gobierno Local.'}, correct:'a', why:{a:'El art. 22.4 LRBRL establece que el Pleno puede delegar el ejercicio de sus atribuciones en el Alcalde y en la Junta de Gobierno Local, excepto las que requieren mayoría cualificada o son indelegables.'}},
{n:39, q:'La concertación de las operaciones de crédito cuya cuantía acumulada, dentro de cada ejercicio económico, exceda del 10% de los recursos ordinarios del presupuesto es competencia atribuida, en todo caso:', o:{a:'A la Junta de Gobierno Local, si estuviera constituida.',b:'Al Pleno municipal en el ayuntamiento o a la Asamblea vecinal en el régimen de Concejo Abierto.',c:'A quien determine el Reglamento Orgánico del ente de que se trate.',d:'Al Alcalde.'}, correct:'b', why:{b:'El art. 22.2.f) LRBRL atribuye al Pleno, en todo caso, las operaciones de crédito cuya cuantía supere el 10% de los recursos ordinarios del presupuesto.'}},
{n:40, q:'Corresponderán al Pleno de un ayuntamiento la concertación de operaciones de crédito cuando el importe acumulado de las operaciones vivas en cada momento supere el 15% de los ingresos corrientes liquidados en el ejercicio anterior...', o:{a:'Cuando sean de Tesorería.',b:'Cuando sean de Intervención.',c:'Cuando sean de Secretaría.',d:'Cuando sean de cualquiera de los citados en las respuestas anteriores.'}, correct:'a', why:{a:'Las operaciones de crédito de tesorería que en conjunto superen el 15% de los ingresos corrientes del ejercicio anterior corresponden al Pleno conforme a la LRBRL.'}},
{n:41, q:'De conformidad con lo establecido en la Ley 7/85, la votación de la moción de censura al Alcalde y de la cuestión de confianza planteada por éste...', o:{a:'Corresponde al Pleno del Ayuntamiento y será pública.',b:'Corresponde al Pleno del Ayuntamiento y se realizará mediante llamamiento nominal, en todo caso.',c:'Corresponde al Pleno del Ayuntamiento y se regirá en todos sus aspectos por lo dispuesto en la legislación electoral general.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'El art. 22.3 LRBRL establece que la moción de censura y la cuestión de confianza corresponden al Pleno, se realizan mediante llamamiento nominal y se rigen por la legislación electoral general; todo ello es correcto.'}},
{n:42, q:'De conformidad con lo establecido en el art.22 de la LRBRL, corresponden al Pleno de un ayuntamiento, en todo caso:', o:{a:'Las atribuciones que deban corresponder al Pleno por exigir para su aprobación una mayoría especial.',b:'Las atribuciones que específicamente se establecen en el art.19 de dicha ley 7/85.',c:'Las atribuciones referidas al ejercicio de acciones judiciales sobre materias de competencia plenaria, en caso de urgencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Entre las atribuciones indelegables del Pleno se incluyen aquellas que por su naturaleza requieren mayoría especial o cualificada, según el art. 22.2 LRBRL.'}},
{n:43, q:'La alteración de la calificación jurídica de los bienes de dominio público debe ser aprobada por:', o:{a:'El Estado.',b:'El Alcalde.',c:'El Pleno.',d:'La Junta de Gobierno Local.'}, correct:'c', why:{c:'El art. 22.2.g) LRBRL atribuye al Pleno la alteración de la calificación jurídica de los bienes demaniales o comunales, que requiere mayoría absoluta.'}},
{n:44, q:'De conformidad con la Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, en municipios del régimen común, le corresponde al Pleno del Ayuntamiento:', o:{a:'Acordar la constitución de las Juntas de Contratación.',b:'Determinar la composición de las Juntas de Contratación, debiendo formar parte de las mismas el secretario o titular del órgano de asesoramiento jurídico y el interventor.',c:'Las respuestas a y b son correctas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Disposición Adicional Segunda de la Ley 9/2017 atribuye al Pleno tanto acordar la constitución de las Juntas de Contratación como determinar su composición.'}},
{n:45, q:'De conformidad con la Disposición Adicional Segunda de la Ley 9/2017 de Contratos del Sector Público, en municipios del régimen común, le corresponde al Pleno del Ayuntamiento:', o:{a:'Ejercer como órgano de contratación, respecto a los contratos que celebre la respectiva entidad local, que no estén atribuidos al Alcalde.',b:'Adjudicación de concesiones sobre bienes de la corporación y adquisición de bienes inmuebles y derechos sujetos a la legislación patrimonial, cuando tal competencia no esté atribuida al Alcalde.',c:'Enajenación del patrimonio municipal no atribuida al Alcalde, y de bienes de valor histórico o artístico.',d:'Le corresponde todo lo reflejado en las respuestas anteriores.'}, correct:'d', why:{d:'La Disposición Adicional Segunda de la Ley 9/2017 atribuye al Pleno todas las funciones de contratación, adjudicación de concesiones y enajenación patrimonial no atribuidas al Alcalde.'}},
{n:46, q:'De conformidad con la Disposición Adicional Segunda de la Ley 9/2017, corresponde al Pleno del Ayuntamiento la aprobación de los pliegos de cláusulas administrativas generales...', o:{a:'En municipios de régimen común.',b:'En municipios de gran población.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Disposición Adicional Segunda de la Ley 9/2017 atribuye al Pleno la aprobación de pliegos de cláusulas administrativas generales tanto en municipios de régimen común como de gran población.'}},
{n:47, q:'El Ayuntamiento Pleno tiene asumida la atribución del control y fiscalización de los órganos de Gobierno ¿puede delegar esta función?', o:{a:'No es una función del Ayuntamiento Pleno, es del Alcalde.',b:'No es una función del Ayuntamiento Pleno, es de la Junta de Gobierno Local.',c:'Sí.',d:'No, esa es una de las funciones indelegables del Pleno.'}, correct:'d', why:{d:'El art. 22.4 LRBRL establece que el control y fiscalización de los órganos de gobierno es una función indelegable del Pleno; no puede transferirse al Alcalde ni a la Junta de Gobierno Local.'}},
{n:48, q:'Las funciones relativas a la identidad del municipio, es una competencia indelegable:', o:{a:'Del Alcalde.',b:'Del Pleno del Ayuntamiento.',c:'De la Junta de Gobierno Local.',d:'De las Comisiones Informativas.'}, correct:'b', why:{b:'Las funciones relativas a la identidad del municipio (nombre, capitalidad, bandera, escudo) son competencias indelegables del Pleno conforme al art. 22 LRBRL.'}},
{n:49, q:'En municipios de régimen común, es competencia delegable del Pleno del Ayuntamiento:', o:{a:'La aprobación de las formas de gestión de los servicios y de los expedientes de municipalización.',b:'La aprobación del Reglamento Orgánico y Ordenanzas.',c:'La aprobación y modificación de los presupuestos.',d:'Todas las citadas son competencias indelegables del Pleno.'}, correct:'d', why:{d:'La aprobación del Reglamento Orgánico, las Ordenanzas, los presupuestos y las formas de gestión de servicios son todas competencias indelegables del Pleno conforme al art. 22.4 LRBRL.'}},
{n:50, q:'En municipios de régimen común, la aprobación de la plantilla de personal y relaciones de puestos de trabajo son competencias del Pleno del Ayuntamiento, que podrá delegarlas:', o:{a:'En la Junta de Gobierno Local.',b:'En la Junta de Gobierno Local o en el Alcalde.',c:'En el Alcalde.',d:'Las citadas en el epígrafe de la pregunta son competencias indelegables del Pleno.'}, correct:'d', why:{d:'La aprobación de la plantilla de personal y de la relación de puestos de trabajo es una competencia indelegable del Pleno conforme al art. 22.4 LRBRL.'}},
{n:51, q:'En municipios de régimen común, el Pleno del Ayuntamiento puede delegar sus competencias referidas a:', o:{a:'La alteración de la calificación jurídica de los bienes de dominio público.',b:'El planteamiento de conflictos de competencia a otras entidades locales.',c:'La votación de la moción de censura.',d:'No puede delegar ninguna de las competencias citadas en las respuestas anteriores.'}, correct:'d', why:{d:'Las tres competencias citadas son indelegables conforme al art. 22.4 LRBRL.'}},
{n:52, q:'Según el art.22.4 LRBRL, el Pleno puede delegar el ejercicio de sus atribuciones en el Alcalde y en la Junta de Gobierno Local, salvo...', o:{a:'La alteración de la calificación jurídica de los bienes demaniales o comunales.',b:'La delegación de funciones del Pleno del Ayuntamiento.',c:'Los acuerdos reflejados en las respuestas a y b necesitan mayoría absoluta del Pleno.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art. 22.4 LRBRL exceptúa de la delegación las competencias del art. 22.2.a) a g), la moción de censura y la cuestión de confianza; las opciones a) y b) no reflejan exactamente esta excepción.'}},
{n:53, q:'El acuerdo de delegación de funciones del Ayuntamiento Pleno se adoptará:', o:{a:'Por mayoría simple.',b:'Por mayoría absoluta.',c:'Por mayoría de 3/4 partes.',d:'El Ayuntamiento Pleno no puede delegar ninguna de sus funciones.'}, correct:'a', why:{a:'El acuerdo de delegación de funciones del Pleno se adopta por mayoría simple, salvo que la Ley exija mayoría cualificada para el asunto concreto que se delega.'}},
{n:54, q:'El acuerdo de delegación de funciones del Ayuntamiento Pleno deberá:', o:{a:'Publicarse en el B.O.E. y contener las materias y condiciones de ejercicio de las mismas.',b:'Publicarse en el B.O.P., y contener las materias y condiciones de ejercicio de las mismas.',c:'Publicarse en el B.O.E. y en el B.O.P., y contener las materias y condiciones de ejercicio de las mismas.',d:'El ayuntamiento Pleno no puede delegar ninguna de sus funciones.'}, correct:'b', why:{b:'El acuerdo de delegación de funciones del Pleno debe publicarse en el Boletín Oficial de la Provincia (B.O.P.) y contener las materias y condiciones de ejercicio.'}},
{n:55, q:'El acuerdo de delegación de funciones del Ayuntamiento Pleno surtirá efectos:', o:{a:'Desde el día siguiente al de su adopción, sin perjuicio de su publicación en el BOP y BOE.',b:'Desde el día siguiente al de su adopción, sin perjuicio de su publicación en el BOP.',c:'A partir de su publicación en el BOE.',d:'A partir de su publicación en el BOP.'}, correct:'b', why:{b:'El acuerdo de delegación surte efectos desde el día siguiente a su adopción, sin perjuicio de su publicación en el Boletín Oficial de la Provincia.'}},
{n:56, q:'El Título V de la Ley 7/85, con el epígrafe "Disposiciones comunes a las entidades locales", regula el régimen de funcionamiento de éstas:', o:{a:'En su Capítulo Primero.',b:'En su Capítulo Segundo.',c:'En su Capítulo Tercero.',d:'En su Capítulo Cuarto.'}, correct:'a', why:{a:'El Capítulo Primero del Título V de la LRBRL regula el régimen de funcionamiento de las entidades locales, incluyendo las reglas sobre sesiones y adopción de acuerdos.'}},
{n:57, q:'En todo caso, el funcionamiento del Pleno de las Corporaciones Locales se ajusta a las reglas establecidas:', o:{a:'En el Título X de la Ley 7/85.',b:'En el art.46.2 de la Ley 7/85.',c:'En el art.36.3 de la Ley 7/85.',d:'En el Título III de la Ley 7/85.'}, correct:'b', why:{b:'El art. 46.2 LRBRL establece las reglas a las que se ajustará, en todo caso, el funcionamiento del Pleno de las Corporaciones Locales.'}},
{n:58, q:'Las sesiones del Pleno del Ayuntamiento podrán ser:', o:{a:'Públicas y privadas, según disponga la convocatoria.',b:'Ordinarias, cuya periodicidad está establecida, y extraordinarias, que pueden ser declaradas urgentes.',c:'Obligatorias y facultativas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 46.2 LRBRL establece que las sesiones del Pleno son ordinarias (periodicidad preestablecida) y extraordinarias, que pueden ser declaradas urgentes.'}},
{n:59, q:'Las sesiones ordinarias del Pleno del Ayuntamiento deberán celebrarse, en todo caso:', o:{a:'Cada tres meses.',b:'Una vez al mes.',c:'Una vez a la semana.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La periodicidad de las sesiones ordinarias varía según el número de habitantes del municipio (mensual, bimestral o trimestral), por lo que ninguna de las opciones anteriores es universalmente correcta.'}},
{n:60, q:'El Pleno del Ayuntamiento celebra sesión ordinaria, como mínimo:', o:{a:'Cada mes en los Ayuntamientos de municipios de más de 20.000 habitantes.',b:'Cada dos meses en los Ayuntamientos de municipios que tengan entre 5.001 y 20.000 habitantes.',c:'Cada tres meses en los municipios de hasta 5.000 habitantes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 46.2.a) LRBRL establece la periodicidad de sesiones ordinarias del Pleno: mensual (más de 20.000 h.), bimestral (5.001-20.000 h.) y trimestral (hasta 5.000 h.).'}},
{n:61, q:'El Pleno del Ayuntamiento celebra sesión extraordinaria:', o:{a:'Cuando así lo decida el Presidente o cuando lo solicite la cuarta parte, al menos, del número legal de concejales.',b:'Sólo cuando lo solicite un tercio del número legal de concejales electos.',c:'Sólo cuando lo solicite la mayoría absoluta del número legal de concejales electos.',d:'Solo cuando así lo decida el Presidente, tras ser solicitado por dos tercios del número legal de concejales.'}, correct:'a', why:{a:'El art. 46.2.b) LRBRL establece que el Pleno celebra sesión extraordinaria cuando lo decide el Presidente o cuando lo solicite la cuarta parte, al menos, del número legal de concejales.'}},
{n:62, q:'Según el art.46.2 LRBRL, ningún concejal podrá solicitar anualmente:', o:{a:'Más de dos sesiones extraordinarias del Pleno.',b:'Más de tres sesiones extraordinarias del Pleno.',c:'Más de cuatro sesiones extraordinarias del Pleno.',d:'Más de cinco sesiones extraordinarias del Pleno.'}, correct:'b', why:{b:'El art. 46.2.b) LRBRL establece que ningún concejal podrá solicitar más de tres sesiones extraordinarias del Pleno por año natural.'}},
{n:63, q:'Solicitado un Pleno extraordinario por la cuarta parte del número legal de concejales, la celebración del mismo no podrá demorarse:', o:{a:'Por más de quince días naturales.',b:'Por más de quince días hábiles.',c:'Por más de veinte días naturales.',d:'Por más de veinte días hábiles.'}, correct:'b', why:{b:'El art. 46.2.b) LRBRL establece que cuando los concejales soliciten un Pleno extraordinario, éste no podrá demorarse más de quince días hábiles desde la solicitud.'}},
{n:64, q:'Si el Presidente no convocase el Pleno extraordinario solicitado en el plazo de 15 días hábiles, quedará automáticamente convocado:', o:{a:'Para las doce horas del décimo día hábil siguiente al de la finalización de dicho plazo.',b:'Para las doce horas del décimo día natural siguiente.',c:'Para las diez horas del décimo día natural siguiente.',d:'Un Pleno extraordinario no puede solicitarse por la cuarta parte de los concejales.'}, correct:'a', why:{a:'El art. 46.2.b) LRBRL establece que si el Presidente no convoca en plazo, el Pleno quedará automáticamente convocado para las 12 horas del décimo día hábil siguiente a la finalización del plazo de 15 días.'}},
{n:65, q:'Las sesiones extraordinarias del Pleno del Ayuntamiento se celebran:', o:{a:'Sin sujeción a ninguna periodicidad.',b:'Con la misma periodicidad que las ordinarias.',c:'Con la periodicidad que establezca el Reglamento Orgánico Municipal.',d:'Sólo cuando existan asuntos urgentes.'}, correct:'b', why:{b:'Las sesiones extraordinarias del Pleno se celebran sin sujeción a periodicidad alguna, convocadas cuando el Presidente lo decida o lo solicite la cuarta parte del número legal de concejales.'}},
{n:66, q:'Con respecto a las sesiones extraordinarias del Ayuntamiento Pleno, indique la respuesta incorrecta:', o:{a:'Se celebran por decisión del Presidente o por la petición de 1/3 de sus miembros.',b:'Ningún concejal puede solicitar más de tres sesiones extraordinarias al año.',c:'Cuando existe petición de sesión extraordinaria por parte de los concejales, la celebración del Pleno no puede demorarse más de quince días hábiles.',d:'En las sesiones extraordinarias urgentes, la convocatoria debe ser ratificada por el propio Pleno.'}, correct:'a', why:{a:'La opción a) es incorrecta: las sesiones extraordinarias se solicitan por la cuarta parte (1/4) del número legal de concejales, no por 1/3 como se indica.'}},
{n:67, q:'El Alcalde, cuando lo estime oportuno, puede delegar la convocatoria y presidencia del Pleno en uno de los Concejales:', o:{a:'Cierto.',b:'Falso. Se trata de una competencia indelegable.',c:'Cierto, pero esta facultad solo está prevista en municipios de gran población.',d:'Cierto, pero esta competencia solo está prevista en municipios de régimen común.'}, correct:'c', why:{c:'El art. 22.1 LRBRL permite al Alcalde delegar la convocatoria y presidencia del Pleno en uno de los Concejales cuando lo estime oportuno.'}},
{n:68, q:'Promover la actividad del Ayuntamiento Pleno y la elaboración del orden del día es competencia:', o:{a:'Del Secretario de la Corporación.',b:'Del Alcalde.',c:'Del Secretario del Alcalde.',d:'De la Junta de Gobierno Local.'}, correct:'b', why:{b:'Promover la actividad del Pleno y elaborar el orden del día es competencia del Alcalde como presidente del Pleno, quien convoca las sesiones y fija el orden del día.'}},
{n:69, q:'Las sesiones del Ayuntamiento Pleno han de convocarse:', o:{a:'Al menos con dos días naturales de antelación.',b:'Al menos con dos días hábiles de antelación.',c:'Al menos con tres días hábiles de antelación.',d:'Al menos con tres días naturales de antelación.'}, correct:'b', why:{b:'El art. 46.2.b) LRBRL establece que las sesiones del Pleno deben convocarse con al menos dos días hábiles de antelación.'}},
{n:70, q:'Las sesiones del Ayuntamiento Pleno han de convocarse, al menos, con dos días naturales de antelación, salvo:', o:{a:'Las extraordinarias urgentes, cuya convocatoria sea ratificada por el Pleno.',b:'Las extraordinarias urgentes, a propuesta de al menos 1/3 de los concejales.',c:'Las extraordinarias solicitadas por al menos 1/3 de los concejales.',d:'Las sesiones del Ayuntamiento Pleno han de convocarse, al menos, con dos días hábiles de antelación.'}, correct:'d', why:{d:'La premisa de la pregunta es incorrecta: el plazo de convocatoria es de dos días hábiles (no naturales). La opción d) corrige esa premisa.'}},
{n:71, q:'Las sesiones del Ayuntamiento Pleno han de convocarse, al menos, con dos días hábiles de antelación, salvo:', o:{a:'Las extraordinarias urgentes, cuya convocatoria sea ratificada por el Pleno.',b:'Las extraordinarias urgentes, a propuesta de al menos 1/3 de los concejales.',c:'Las extraordinarias solicitadas por al menos 1/3 de los concejales.',d:'Las sesiones han de convocarse al menos con tres días naturales de antelación.'}, correct:'a', why:{a:'El art. 46.2 LRBRL establece el plazo de dos días hábiles salvo las sesiones extraordinarias urgentes, cuya convocatoria debe ser ratificada por el propio Pleno.'}},
{n:72, q:'El orden del día de las sesiones del Pleno será fijado por el Alcalde, asistido por el Secretario/a, y en él sólo pueden incluirse:', o:{a:'Aquellos asuntos previamente dictaminados, informados o sometidos a consulta de la Comisión Informativa correspondiente.',b:'Aquellos asuntos que, por extraordinaria urgencia, hayan sido solicitados por al menos un tercio de los concejales.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art. 46.2.b) LRBRL establece que en el orden del día del Pleno solo pueden incluirse asuntos previamente dictaminados, informados o sometidos a consulta de la Comisión Informativa correspondiente.'}},
{n:73, q:'El Pleno del Ayuntamiento se constituye válidamente con la asistencia:', o:{a:'De dos tercios del número legal de sus miembros.',b:'De tres quintos del número legal de sus miembros.',c:'De un tercio del número legal de sus miembros, que nunca puede ser inferior a tres, salvo en municipios de hasta 100 residentes que no funcionen en régimen de Concejo abierto.',d:'De la mayoría absoluta de sus miembros.'}, correct:'c', why:{c:'El art. 46.2.c) LRBRL establece que el Pleno se constituye con un tercio del número legal de miembros, nunca inferior a tres, salvo en municipios de hasta 100 residentes que no funcionen en Concejo abierto.'}},
{n:74, q:'En municipios de hasta 100 residentes, que no funcionen en régimen de concejo abierto, el Pleno se constituye válidamente con un número de asistentes que no puede ser inferior a:', o:{a:'Dos.',b:'Tres.',c:'Cuatro.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 46.2.c) LRBRL establece que en municipios de hasta 100 residentes el quórum mínimo para constituir válidamente el Pleno es de dos miembros.'}},
{n:75, q:'De no alcanzarse el quórum para la celebración en primera convocatoria de una sesión del Pleno:', o:{a:'La sesión se celebrará en segunda convocatoria cinco días después.',b:'La sesión se celebrará en segunda convocatoria cuatro días después.',c:'La sesión se celebrará en segunda convocatoria tres días después.',d:'La sesión se celebrará en segunda convocatoria dos días después.'}, correct:'d', why:{d:'El art. 46.2.c) LRBRL establece que si no se alcanza el quórum en primera convocatoria, la sesión se celebrará en segunda convocatoria dos días después.'}},
{n:76, q:'De no alcanzarse el quórum en segunda convocatoria de una sesión del Pleno:', o:{a:'El Presidente dejará sin efecto la convocatoria.',b:'La sesión se celebrará tres días hábiles después.',c:'La sesión se celebrará cinco días hábiles después.',d:'La sesión se celebrará cinco días naturales después.'}, correct:'a', why:{a:'El art. 46.2.c) LRBRL establece que si tampoco se alcanza el quórum en segunda convocatoria, el Presidente dejará sin efecto la convocatoria.'}},
{n:77, q:'Respecto a la asistencia a las sesiones del Pleno del Ayuntamiento...', o:{a:'En todo caso, deben asistir el Presidente y el Secretario, o quienes les sustituyan.',b:'En ausencia del Presidente, el Pleno queda válidamente constituido si hay quórum.',c:'En ausencia del Presidente, el Pleno será presidido por el miembro de mayor edad entre los presentes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 46.2 LRBRL y el ROF establecen que deben asistir el Presidente y Secretario o sus sustitutos, que el Pleno puede constituirse válidamente sin el Presidente si hay quórum, y que en ese caso lo preside el miembro de mayor edad.'}},
{n:78, q:'En las sesiones del Pleno del Ayuntamiento:', o:{a:'La adopción de acuerdos se produce mediante votación ordinaria, salvo que el propio Pleno acuerde la votación nominal.',b:'El voto puede ser afirmativo, negativo, o de abstención.',c:'Los acuerdos se adoptan por mayoría simple, salvo los que la ley prevé que lo sean por mayorías cualificadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 47 LRBRL establece que los acuerdos se adoptan por mayoría simple mediante votación ordinaria (salvo acuerdo en contrario), y el voto puede ser afirmativo, negativo o de abstención.'}},
{n:79, q:'Cuando concurran situaciones excepcionales de fuerza mayor o catástrofes que impidan el normal funcionamiento presencial del Pleno, éste podrá constituirse y celebrar sesiones a distancia por medios electrónicos, siempre que se cumplan:', o:{a:'Los requisitos establecidos en el art.43.6 de la Ley 7/85.',b:'Los requisitos establecidos en el art.46.3 de la Ley 7/85.',c:'Los requisitos establecidos en el art.43.3 de la Ley 7/85.',d:'Los requisitos establecidos en el art.49.3 de la Ley 7/85.'}, correct:'b', why:{b:'El art. 46.3 LRBRL regula la posibilidad de que el Pleno celebre sesiones a distancia por medios electrónicos en situaciones de emergencia o catástrofe.'}},
{n:80, q:'El Ayuntamiento Pleno podrá constituirse y celebrar sesiones a distancia por medios electrónicos, siempre que:', o:{a:'La situación excepcional haya sido aprobada previamente en sesión plenaria presencial.',b:'Los miembros participantes aporten previamente su credencial en vigor.',c:'Se asegure la comunicación en tiempo real durante la sesión, garantizando el carácter público o secreto según proceda.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 46.3 LRBRL exige que en las sesiones telemáticas del Pleno se asegure la comunicación en tiempo real y se garantice el carácter público o secreto de las sesiones según proceda.'}},
{n:81, q:'El Ayuntamiento Pleno podrá celebrar sesiones telemáticas, siempre que:', o:{a:'Los miembros participantes estén en territorio español y acrediten su identidad.',b:'La situación excepcional sea apreciada por el Alcalde o quien le sustituya.',c:'Se asegure la comunicación en tiempo real garantizando el carácter público o secreto según proceda.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 46.3 LRBRL exige para las sesiones telemáticas que los miembros estén en territorio español y acrediten su identidad, que la situación sea apreciada por el Alcalde, y que se garantice comunicación en tiempo real.'}},
{n:82, q:'Respecto al funcionamiento a distancia del Pleno, se consideran medios electrónicos válidos los que garanticen adecuadamente:', o:{a:'La seguridad tecnológica.',b:'La efectiva participación política de sus miembros.',c:'La validez del debate y votación de los acuerdos que se adopten.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 46.3 LRBRL exige que los medios electrónicos garanticen la seguridad tecnológica, la efectiva participación política y la validez del debate y votaciones.'}},
{n:83, q:'Indique cuál de los siguientes acuerdos no necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La aprobación de la delimitación del término municipal.',b:'La municipalización de actividades en régimen de monopolio.',c:'La aprobación de una ordenanza fiscal.',d:'La cesión gratuita de bienes a otras administraciones.'}, correct:'c', why:{c:'La aprobación de una ordenanza fiscal se adopta por mayoría simple. Los otros acuerdos sí requieren mayoría absoluta según el art. 47.2 LRBRL.'}},
{n:84, q:'De los siguientes, indique el acuerdo que no necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La aprobación y modificación del Reglamento Orgánico de la Corporación.',b:'La aprobación del presupuesto del Ayuntamiento.',c:'La enajenación de bienes cuando su cuantía exceda del 20 % de los recursos ordinarios del presupuesto.',d:'La transferencia de funciones o actividades a otras administraciones públicas.'}, correct:'b', why:{b:'La aprobación del presupuesto se adopta por mayoría simple, no requiere mayoría absoluta. El Reglamento Orgánico, la enajenación relevante y la transferencia de funciones sí la requieren.'}},
{n:85, q:'De los siguientes, indique el acuerdo que necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La alteración de la calificación jurídica de los bienes demaniales o comunales.',b:'La delegación de funciones del Pleno del Ayuntamiento.',c:'Los acuerdos reflejados en las respuestas a y b necesitan mayoría absoluta.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 47.2 LRBRL establece que la alteración de la calificación jurídica de los bienes demaniales o comunales requiere mayoría absoluta del número legal de miembros del Pleno.'}},
{n:86, q:'De los siguientes, indique el acuerdo que necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'Los acuerdos sobre el planeamiento general previstos en la legislación Urbanística.',b:'El ejercicio de acciones judiciales y administrativas y la defensa jurídica del Pleno.',c:'El planteamiento de conflictos de competencia a otras administraciones.',d:'Todos los acuerdos anteriores necesitan mayoría absoluta del Pleno.'}, correct:'a', why:{a:'El art. 47.2.ll) LRBRL establece que los acuerdos sobre planeamiento general urbanístico requieren mayoría absoluta del número legal de miembros del Pleno.'}},
{n:87, q:'De los siguientes, indique el acuerdo que necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La alteración del nombre y de la capitalidad del municipio.',b:'La creación y supresión de municipios y alteración de términos municipales.',c:'La creación de entidades de ámbito territorial inferior al municipio.',d:'Todos los acuerdos anteriores necesitan mayoría absoluta del Pleno.'}, correct:'d', why:{d:'El art. 47.2 LRBRL exige mayoría absoluta para la alteración del nombre y capitalidad del municipio, la creación/supresión de municipios y la creación de entidades de ámbito territorial inferior.'}},
{n:88, q:'De los siguientes, indique el acuerdo que necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La aprobación de operaciones financieras o de crédito superiores al 10% de los recursos ordinarios del presupuesto.',b:'La concesión de bienes o servicios por más de cinco años cuando su cuantía exceda del 20 % de los recursos ordinarios del presupuesto.',c:'Los acuerdos reflejados en las respuestas a y b necesitan mayoría absoluta.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 47.2 LRBRL exige mayoría absoluta tanto para las operaciones de crédito que superen el 10% del presupuesto como para la concesión de bienes o servicios por más de cinco años que exceda el 20% de los recursos ordinarios.'}},
{n:89, q:'De los siguientes, indique el acuerdo que necesita de mayoría absoluta del Pleno para ser aprobado:', o:{a:'La adopción o modificación de su bandera, enseña o escudo.',b:'La cesión por cualquier título del aprovechamiento de bienes comunales.',c:'La creación, modificación o disolución de mancomunidades y otras organizaciones asociativas.',d:'Todos los acuerdos anteriores necesitan mayoría absoluta del Pleno.'}, correct:'d', why:{d:'El art. 47.2 LRBRL exige mayoría absoluta para la modificación de símbolos municipales, la cesión de bienes comunales y la creación/modificación/disolución de mancomunidades.'}},
{n:90, q:'El voto de los concejales del Pleno es personal e indelegable y en caso de empate, tras una nueva votación, si éste persistiere:', o:{a:'Se celebrará una nueva sesión del Pleno tres días hábiles después.',b:'Decidirá el voto de calidad del Alcalde.',c:'Se celebrará una nueva sesión del Pleno dos días hábiles después.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 47.3 LRBRL establece que si persiste el empate tras una nueva votación, el Alcalde (o Presidente del órgano) decide mediante su voto de calidad.'}},
{n:91, q:'Las sesiones del Ayuntamiento Pleno son de carácter:', o:{a:'Público.',b:'Privado.',c:'Semipúblico.',d:'Semiprivado.'}, correct:'a', why:{a:'El art. 46.2.e) LRBRL establece que las sesiones del Pleno son de carácter público, salvo que se declare secreto el debate y votación de algún asunto específico.'}},
{n:92, q:'Con respecto a las sesiones del Pleno, indique la afirmación correcta:', o:{a:'Se celebrarán en la Casa Consistorial, salvo en casos de fuerza mayor.',b:'Serán públicas.',c:'De cada sesión se extenderá acta por el Secretario de la Corporación o Secretario General del Pleno, según los casos.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'d', why:{d:'El art. 46.2 LRBRL y el ROF establecen las tres afirmaciones: celebración en la Casa Consistorial salvo fuerza mayor, carácter público y levantamiento de acta por el Secretario.'}},
{n:93, q:'Con respecto a las sesiones del Pleno, indique la afirmación correcta:', o:{a:'Son de carácter semipúblico.',b:'Se celebrarán siempre en la Casa Consistorial.',c:'El público asistente a las sesiones no podrá intervenir en éstas, ni tampoco podrán permitirse manifestaciones de agrado o desagrado.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'c', why:{c:'El art. 46.2 LRBRL establece que el público asistente no puede intervenir en las sesiones del Pleno, ni se permiten manifestaciones de agrado o desagrado.'}},
{n:94, q:'Las sesiones del Pleno son públicas; no obstante, podrán declararse secretos el debate y la votación de algunos asuntos, cuando así se acuerde:', o:{a:'Por mayoría simple.',b:'Por mayoría absoluta.',c:'Las sesiones del Pleno son siempre públicas.',d:'Por mayoría de dos tercios.'}, correct:'b', why:{b:'El art. 70.1 LRBRL establece que el debate y la votación pueden declararse secretos por mayoría absoluta del Pleno, cuando así lo exija la naturaleza del asunto.'}},
{n:95, q:'Las sesiones del Pleno son públicas; no obstante, podrán declararse secretos el debate y votación de aquellos asuntos:', o:{a:'Que puedan afectar al derecho a la libertad.',b:'Que puedan afectar al derecho al honor, a la intimidad personal y familiar y a la propia imagen de los ciudadanos.',c:'En ningún caso, ya que las sesiones del Pleno son siempre públicas.',d:'Que puedan afectar a los derechos citados en las respuestas a) y b).'}, correct:'b', why:{b:'El art. 70.1 LRBRL permite declarar secretos el debate y votación de asuntos que afecten al derecho al honor, a la intimidad personal y familiar y a la propia imagen de los ciudadanos.'}},
{n:96, q:'En las sesiones del Pleno del Ayuntamiento:', o:{a:'Se permitirá en todo caso la grabación de las reuniones por parte de particulares.',b:'El consistorio puede promover la grabación y publicación de las reuniones en plataformas accesibles a la ciudadanía, incluso en tiempo real.',c:'El presidente, en casos extremos, puede ordenar la expulsión de cualquier asistente que impida el normal desarrollo de la sesión.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La normativa de régimen local permite la grabación de sesiones y su difusión, y faculta al Presidente para expulsar a asistentes que perturben el normal desarrollo de la sesión.'}},
{n:97, q:'De conformidad con el artículo 139 de la Ley 8/2010 de Régimen Local de la Comunitat Valenciana...', o:{a:'A las sesiones del Pleno tendrán acceso los medios de comunicación.',b:'A las sesiones del Pleno tendrá acceso la ciudadanía en general, en las condiciones que fije el Reglamento Orgánico Municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 139 de la Ley 8/2010 CV establece el acceso de los medios de comunicación y de la ciudadanía en general a las sesiones del Pleno.'}},
{n:98, q:'La denominación "Comisión de Gobierno Local" fue sustituida por "Junta de Gobierno Local" mediante la modificación de la ley 7/1985, realizada por:', o:{a:'La Ley 57/2003.',b:'El Real Decreto Legislativo 781/1986.',c:'El Real Decreto 2568/1986.',d:'El Real Decreto 188/1986.'}, correct:'a', why:{a:'La Ley 57/2003, de medidas para la modernización del gobierno local, sustituyó la denominación "Comisión de Gobierno Local" por "Junta de Gobierno Local" en la LRBRL.'}},
{n:99, q:'De conformidad con el art.20.1 LRBRL, la Junta de Gobierno Local existe:', o:{a:'En todos los municipios con población superior a 5.000 habitantes.',b:'En los municipios con población inferior a 5.000 habitantes, cuando así lo disponga su Reglamento Orgánico.',c:'En los municipios con población inferior a 5.000 habitantes, cuando así lo acuerde el Pleno.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 20.1 LRBRL establece que la Junta de Gobierno Local existe en municipios de más de 5.000 h. y en los de menos cuando lo disponga el Reglamento Orgánico o lo acuerde el Pleno.'}},
{n:100, q:'El art.23 LRBRL establece que:', o:{a:'La Junta de Gobierno Local se integra por el Alcalde y concejales no superiores al tercio del número legal.',b:'Los Concejales que integran la Junta son nombrados y separados libremente por el Alcalde, dando cuenta al Pleno.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 23.1 LRBRL establece que los miembros de la Junta de Gobierno Local son nombrados y separados libremente por el Alcalde, dando cuenta al Pleno.'}},
{n:101, q:'La Junta de Gobierno Local existirá obligatoriamente:', o:{a:'En todos los municipios.',b:'En los que tengan más de 1.000 habitantes.',c:'En los municipios con población de derecho superior a 5.000 habitantes.',d:'En los municipios con población inferior a 10.000 habitantes.'}, correct:'c', why:{c:'El art. 20.1.b) LRBRL establece que la Junta de Gobierno Local es órgano necesario en todos los municipios con población de derecho superior a 5.000 habitantes.'}},
{n:102, q:'La Junta de Gobierno Local es un órgano de carácter:', o:{a:'Necesario en los municipios con población de derecho superior a 5.000 habitantes.',b:'Potestativo para los municipios con población inferior a 5.000 habitantes.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Junta de Gobierno Local es necesaria en municipios de más de 5.000 h. y potestativa en los de hasta 5.000 h. si el Reglamento Orgánico o el Pleno así lo establecen.'}},
{n:103, q:'En municipios de régimen común, la Junta de Gobierno Local estará integrada por:', o:{a:'El Alcalde y los Concejales que éste determine.',b:'El Alcalde, que la preside, y un número de Concejales no superior al tercio del número legal de los mismos.',c:'El Alcalde y un número de Concejales no superior a la mitad del número legal de los mismos.',d:'El Alcalde y los Tenientes de Alcalde.'}, correct:'b', why:{b:'El art. 23.1 LRBRL establece que en municipios de régimen común la Junta de Gobierno Local se integra por el Alcalde, que la preside, y concejales en número no superior al tercio del número legal.'}},
{n:104, q:'Los miembros de la Junta de Gobierno Local de un Ayuntamiento son nombrados y separados:', o:{a:'Por el Alcalde.',b:'Por el Pleno del Ayuntamiento.',c:'Por los Tenientes de Alcalde.',d:'Por la Comisión Especial nombrada por el Alcalde.'}, correct:'a', why:{a:'El art. 23.1 LRBRL establece que los miembros de la Junta de Gobierno Local son nombrados y separados libremente por el Alcalde, dando cuenta al Pleno.'}},
{n:105, q:'Según el art.46 del RDL 781/1986, en municipios de régimen común, la Junta de Gobierno Local celebrará sesión ordinaria:', o:{a:'Con la periodicidad que establezca el Reglamento Orgánico de la Corporación.',b:'Con la periodicidad que establezca el Alcalde.',c:'Con la periodicidad que establezca el Pleno.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 46 RDL 781/1986 establece que la Junta de Gobierno Local celebra sesión ordinaria con la periodicidad que establezca el Reglamento Orgánico de la Corporación.'}},
{n:106, q:'Según el art.46 del RDL 781/1986, en municipios de régimen común, la fijación del día en que deba celebrarse la sesión ordinaria de la Junta de Gobierno Local, corresponde:', o:{a:'Al Pleno del Ayuntamiento.',b:'A su Presidente.',c:'A la Comisión Informativa de Asuntos Internos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'La fijación del día de la sesión ordinaria de la Junta de Gobierno Local corresponde a su Presidente (el Alcalde), conforme al art. 46 RDL 781/1986.'}},
{n:107, q:'Según el art.112 del RD 2568/1986, en municipios de régimen común, la sesión constitutiva de la Junta de Gobierno Local se celebrará:', o:{a:'Dentro de los 10 días siguientes a la designación de los miembros por el Alcalde.',b:'Dentro de los 15 días siguientes a la designación de los miembros por el Alcalde.',c:'Dentro de los 20 días siguientes a la designación de los miembros por el Alcalde.',d:'En el plazo de un mes desde la designación de sus miembros.'}, correct:'a', why:{a:'El art. 112 ROF (RD 2568/1986) establece que la sesión constitutiva de la Junta de Gobierno Local se celebrará dentro de los 10 días siguientes a la designación de sus miembros por el Alcalde.'}},
{n:108, q:'Con respecto a las sesiones de la Junta de Gobierno Local en municipios de régimen común, indique la afirmación incorrecta:', o:{a:'No son públicas, sin perjuicio de la publicidad de los acuerdos adoptados.',b:'Para su válida constitución se requiere la asistencia de la mayoría simple de sus componentes, en primera convocatoria.',c:'En el plazo de diez días deberá enviarse a todos los miembros de la Corporación copia del acta de la sesión celebrada.',d:'Celebrará sesión ordinaria con la periodicidad que establezca el Reglamento Orgánico.'}, correct:'b', why:{b:'La opción b) es incorrecta: la válida constitución de la Junta de Gobierno Local requiere la mayoría absoluta de sus componentes en primera convocatoria, no la mayoría simple.'}},
{n:109, q:'Como excepción, la STC 161/2013 interpreta que es obligatoria la publicidad de las sesiones de la Junta de Gobierno Local:', o:{a:'Cuando actúen en el ejercicio de competencias delegadas por el Pleno.',b:'Cuando actúen en el ejercicio de competencias delegadas por el Alcalde.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'La STC 161/2013 declaró obligatoria la publicidad de las sesiones de la Junta de Gobierno Local cuando actúa en ejercicio de competencias delegadas por el Pleno.'}},
{n:110, q:'Con respecto a las sesiones de la Junta de Gobierno Local en municipios de régimen común, indique la afirmación correcta:', o:{a:'Para su válida constitución se requiere la asistencia de la mayoría absoluta de sus componentes, en primera convocatoria.',b:'En segunda convocatoria, es suficiente la asistencia de la tercera parte de sus miembros, siempre que su número sea superior a tres.',c:'Celebrará sesión ordinaria con la periodicidad que establezca el Reglamento Orgánico.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'d', why:{d:'El art. 113 ROF establece que la Junta de Gobierno necesita mayoría absoluta en primera convocatoria y tercera parte en segunda (si superior a tres), y celebra sesiones ordinarias con la periodicidad del ROF.'}},
{n:111, q:'En municipios de régimen común, corresponde a la Junta de Gobierno Local:', o:{a:'La asistencia al Alcalde en el ejercicio de sus atribuciones y el ejercicio de las que el Alcalde u otro órgano le delegue, o le atribuyan las leyes.',b:'Ejercitar acciones administrativas y judiciales en caso de urgencia.',c:'Todas las atribuciones en materia de personal que no competen al Pleno.',d:'La organización de los servicios administrativos de la Corporación.'}, correct:'a', why:{a:'El art. 23.2 LRBRL establece que en municipios de régimen común la Junta de Gobierno Local asiste al Alcalde y ejerce las atribuciones que éste u otro órgano le delegue o las leyes le atribuyan.'}},
{n:112, q:'En municipios de régimen común, el alcalde puede delegar la aprobación de los instrumentos del Planeamiento General que sean de su competencia:', o:{a:'En el Pleno.',b:'En un concejal.',c:'En la Junta de Gobierno Local.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El Alcalde puede delegar en la Junta de Gobierno Local la aprobación de los instrumentos del Planeamiento General de su competencia, conforme a la LRBRL.'}},
{n:113, q:'En municipios de régimen común ¿Puede el Pleno de un Ayuntamiento delegar sus funciones en la Junta de Gobierno Local?', o:{a:'Sí, todas.',b:'No, ninguna.',c:'Sí, excepto las que tienen carácter indelegable.',d:'No, salvo que el Alcalde así lo estime oportuno.'}, correct:'c', why:{c:'El art. 22.4 LRBRL establece que el Pleno puede delegar en la Junta de Gobierno Local las atribuciones no indelegables.'}},
{n:114, q:'La Sentencia del Tribunal Constitucional 103/2013 declaró inconstitucional:', o:{a:'La facultad que se reconoce al Alcalde para nombrar miembros de la Junta de Gobierno Local a aquellos que no ostentan la condición de concejales.',b:'La regulación actual de la Junta de Gobierno Local.',c:'La facultad que se reconoce al Alcalde para nombrar y cesar a los miembros de la Junta de Gobierno Local.',d:'La regulación actual del Pleno del Ayuntamiento.'}, correct:'a', why:{a:'La STC 103/2013 declaró inconstitucional la facultad de nombrar como miembros de la Junta de Gobierno Local a personas que no ostentan la condición de concejales.'}},
{n:115, q:'Excepcionalmente, cuando el Pleno no alcance la mayoría necesaria en primera votación, la Junta de Gobierno Local tendrá competencia para aprobar:', o:{a:'El presupuesto del ejercicio siguiente, siempre que exista un presupuesto prorrogado.',b:'Los planes económico-financieros, de reequilibrio y de ajuste de la LO 2/2012.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LRBRL establece que cuando el Pleno no alcance la mayoría necesaria, la Junta de Gobierno puede aprobar tanto el presupuesto prorrogado como los planes de la LO 2/2012.'}},
{n:116, q:'Excepcionalmente, cuando el Pleno no alcance la mayoría necesaria en primera votación, la Junta de Gobierno Local tendrá competencia para aprobar:', o:{a:'Los planes de saneamiento de la corporación o los de reducción de deudas.',b:'La entrada de la corporación en los mecanismos extraordinarios de financiación de la LO 2/2012.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LRBRL establece que la Junta de Gobierno puede también aprobar los planes de saneamiento y la adhesión a los mecanismos extraordinarios de financiación de la LO 2/2012.'}},
{n:117, q:'Las previsiones de excepcionalidad de la disposición adicional decimosexta de la LRBRL, que atribuye competencias a la Junta de Gobierno Local para determinados acuerdos, fueron declaradas inconstitucionales:', o:{a:'Por la STC 116/2011.',b:'Por la STC 111/2016.',c:'Por la STC 108/2018.',d:'Por la STC 118/2018.'}, correct:'b', why:{b:'La STC 111/2016 declaró inconstitucionales y nulas las previsiones de excepcionalidad de la disposición adicional decimosexta de la LRBRL.'}},
{n:118, q:'De conformidad con la Ley 8/2010 de Régimen Local de la CV, en los municipios de más de 5.000 habitantes, existirán Comisiones Informativas que tengan por objeto:', o:{a:'El estudio, informe o consulta de los asuntos que han de ser sometidos a la decisión del Pleno.',b:'El seguimiento de la gestión del Alcalde, la Junta de Gobierno Local y los concejales con delegaciones.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 32 de la Ley 8/2010 CV establece que las Comisiones Informativas tienen por objeto el estudio e informe de asuntos a decidir por el Pleno y el seguimiento de la gestión municipal.'}},
{n:119, q:'El objeto de las Comisiones informativas municipales es:', o:{a:'Asesoramiento del Alcalde.',b:'Estudio y debate de los asuntos que deban ser sometidos a la decisión del Pleno.',c:'Adoptar decisiones sobre asuntos que ha de tratar el Pleno.',d:'Estas Comisiones no tienen ningún objeto concreto.'}, correct:'b', why:{b:'El objeto de las Comisiones Informativas es el estudio y debate de los asuntos a someter al Pleno, emitiendo dictamen previo sin funciones resolutorias.'}},
{n:120, q:'La creación de una Comisión informativa a nivel municipal:', o:{a:'Es obligatoria.',b:'Es potestativa, salvo en los casos previstos en la ley.',c:'Es una facultad del Alcalde.',d:'Es una facultad de la Junta de Gobierno Local.'}, correct:'b', why:{b:'La creación de Comisiones Informativas es potestativa salvo en los casos en que la ley la exige obligatoriamente, como en municipios de más de 5.000 h. según la Ley 8/2010 CV.'}},
{n:121, q:'Todos los grupos políticos integrantes de la Corporación tendrán derecho a participar en las Comisiones informativas municipales y la composición de éstas:', o:{a:'Será la que determine libremente el Alcalde.',b:'Será la que determine la Junta de Gobierno Local.',c:'Será la que determine el Pleno.',d:'Será en proporción al número de concejales que tengan en el Pleno.'}, correct:'d', why:{d:'La composición de las Comisiones Informativas es proporcional al número de concejales que cada grupo político tenga en el Pleno.'}},
{n:122, q:'Cuando por la composición de la Corporación no pueda conseguirse participación proporcional de concejales en las comisiones, podrá optarse por repartir los puestos de modo que la formación de mayorías sea la misma que en el Pleno, o integrar las comisiones con igual número de miembros por grupo...', o:{a:'Correcto, aplicándose el sistema de voto ponderado.',b:'Incorrecto.',c:'Correcto, aplicándose el sistema de voto relativo.',d:'Incorrecto; la composición la decide el Alcalde.'}, correct:'a', why:{a:'Cuando no es posible la proporcionalidad exacta, se aplica el sistema de voto ponderado para mantener la misma distribución de mayorías que en el Pleno.'}},
{n:123, q:'Las Comisiones informativas municipales podrán ser:', o:{a:'Permanentes o especiales.',b:'Urgentes u ordinarias.',c:'Públicas o privadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Las Comisiones Informativas municipales pueden ser permanentes (estables para áreas concretas) o especiales (temporales para asuntos específicos).'}},
{n:124, q:'De acuerdo con la Ley 8/2010 de Régimen Local de la CV, respecto a las Comisiones Informativas Municipales, indique la afirmación correcta:', o:{a:'Las Permanentes son aquellas que se constituyen con carácter general.',b:'Corresponde al Pleno, a propuesta del Alcalde, determinar el número, denominación y funciones de las Comisiones Permanentes.',c:'Las Especiales son temporales, de carácter específico, sin necesidad de propuesta previa del Alcalde.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'d', why:{d:'El art. 33 de la Ley 8/2010 CV establece que las Comisiones Permanentes se constituyen con carácter general a propuesta del Alcalde ante el Pleno, y las Especiales son temporales sin propuesta previa del Alcalde.'}},
{n:125, q:'En el acuerdo de creación de las Comisiones Informativas Municipales se determinará la composición de éstas, teniendo en cuenta:', o:{a:'Que el Alcalde es el presidente de todas ellas, aunque podrá delegar la presidencia.',b:'Que la adscripción de miembros se realiza mediante escrito del portavoz del grupo, dirigido al Alcalde y del que se da cuenta al Pleno.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'d', why:{d:'El art. 33 Ley 8/2010 CV no establece exactamente que el Alcalde sea presidente de todas las comisiones ni la forma de adscripción descrita; las opciones a) y b) no reflejan fielmente la regulación.'}},
{n:126, q:'La adscripción de los Concejales a cada Comisión informativa se realizará:', o:{a:'Mediante designación del Alcalde, previa solicitud del Concejal interesado.',b:'Mediante designación de la Junta de Gobierno Local.',c:'Mediante designación del Pleno, previa solicitud del Concejal interesado.',d:'Mediante escrito del Portavoz de cada grupo político dirigido al Alcalde, del que se dará cuenta al Pleno.'}, correct:'d', why:{d:'La adscripción de los Concejales a las Comisiones Informativas se realiza mediante escrito del Portavoz de cada grupo político dirigido al Alcalde, del que se da cuenta al Pleno.'}},
{n:127, q:'Las Comisiones informativas del Ayuntamiento carecen de funciones resolutorias pero, en todo caso, su dictamen:', o:{a:'Será preceptivo.',b:'Será vinculante.',c:'Será preceptivo y vinculante.',d:'Será preceptivo, pero no vinculante.'}, correct:'d', why:{d:'El dictamen de las Comisiones Informativas es preceptivo (obligatorio previo al Pleno) pero no vinculante (el Pleno puede separarse del mismo motivadamente).'}},
{n:128, q:'De acuerdo con la Ley 8/2010 de Régimen Local de la CV, el quórum de asistencia para la válida constitución de las Comisiones Informativas Municipales será:', o:{a:'De la mayoría absoluta del número legal de sus miembros.',b:'De 2/3 del número legal de sus miembros, debiendo mantenerse durante toda la sesión.',c:'De 1/3 del número legal de sus miembros, debiendo mantenerse durante toda la sesión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 33 de la Ley 8/2010 CV establece que el quórum para la válida constitución de las Comisiones Informativas es de 1/3 del número legal de sus miembros, manteniéndose durante toda la sesión.'}},
{n:129, q:'Con respecto a la Comisión Especial de Cuentas, señale la afirmación correcta:', o:{a:'Sus dictámenes son preceptivos.',b:'El contenido de su actividad se encuentra marcado por las normas que regulan el control de las cuentas de los Ayuntamientos.',c:'Es de existencia obligatoria en todos los ayuntamientos.',d:'Son correctas todas las afirmaciones anteriores.'}, correct:'d', why:{d:'La Comisión Especial de Cuentas es obligatoria en todos los Ayuntamientos, sus dictámenes son preceptivos y su actividad se rige por las normas de control de cuentas locales.'}},
{n:130, q:'¿Qué Concejales pueden formar parte de la Comisión Especial de Cuentas?', o:{a:'Todos.',b:'Los que pertenezcan a la Junta de Gobierno Local.',c:'Los que designe el Alcalde.',d:'Solamente los Tenientes de Alcalde.'}, correct:'a', why:{a:'Todos los Concejales tienen derecho a participar en la Comisión Especial de Cuentas, dado su carácter de órgano de control de la gestión económico-financiera municipal.'}},
{n:131, q:'De acuerdo con la Ley 8/2010 de Régimen Local de la CV, respecto a la Comisión Especial de Cuentas, indique la respuesta correcta:', o:{a:'Se reunirá necesariamente antes del 1 de junio de cada año para examinar las cuentas generales.',b:'Los miembros tienen a su disposición las cuentas generales al menos 20 días antes de la primera reunión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 8/2010 CV establece que la Comisión Especial de Cuentas se reunirá necesariamente antes del 1 de junio de cada año para examinar las cuentas generales.'}},
{n:132, q:'La Comisión Especial de Cuentas ¿tiene funciones resolutorias?', o:{a:'No, nunca.',b:'Sí, siempre.',c:'No, excepto que el Pleno le otorgue tal potestad.',d:'Solo en materia presupuestaria.'}, correct:'a', why:{a:'La Comisión Especial de Cuentas es un órgano consultivo y de control; no tiene funciones resolutorias, que corresponden al Pleno.'}},
{n:133, q:'La presidencia de la Comisión Especial de Cuentas le corresponde:', o:{a:'Siempre al Alcalde.',b:'Al Concejal de mayor edad.',c:'Al Concejal del grupo político mayoritario.',d:'Al Alcalde o miembro de la misma en el que éste delegue.'}, correct:'d', why:{d:'La presidencia de la Comisión Especial de Cuentas corresponde al Alcalde, que puede delegarla en un miembro de la misma.'}},
{n:134, q:'La Comisión Especial de Cuentas podrá celebrar reuniones preparatorias:', o:{a:'Si su presidente lo decide.',b:'Si así lo solicita una cuarta parte, al menos, del número legal de miembros.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'La Comisión Especial de Cuentas puede celebrar reuniones preparatorias tanto por decisión del presidente como a petición de al menos una cuarta parte de sus miembros.'}},
{n:135, q:'La Comisión Especial de Cuentas puede actuar como Comisión Informativa Permanente para asuntos de economía y hacienda:', o:{a:'Si así lo acuerda la Junta de Gobierno.',b:'Si así se determina en el Reglamento Orgánico o mediante acuerdo plenario.',c:'Si así lo determina el Alcalde.',d:'En ningún caso.'}, correct:'b', why:{b:'La Comisión Especial de Cuentas puede actuar como Comisión Informativa Permanente para asuntos de economía y hacienda si así lo determina el Reglamento Orgánico o un acuerdo plenario.'}},
{n:136, q:'Las cuentas generales estarán a disposición de los miembros de la Comisión Especial de Cuentas, como mínimo:', o:{a:'Quince días antes de la primera reunión.',b:'Diez días antes de la primera reunión.',c:'Tres días antes de la primera reunión.',d:'Dos días antes de la primera reunión.'}, correct:'a', why:{a:'La normativa de régimen local establece que la documentación de cuentas debe estar a disposición de los miembros de la Comisión al menos quince días antes de la primera reunión.'}},
{n:137, q:'La Comisión Especial de Sugerencias y Reclamaciones existirá:', o:{a:'En todos los municipios de gran población.',b:'En aquellos municipios en los que el Pleno así lo acuerde por mayoría absoluta.',c:'En aquellos municipios que así lo disponga su Reglamento Orgánico.',d:'En todos los municipios citados en las respuestas anteriores.'}, correct:'d', why:{d:'La Comisión Especial de Sugerencias y Reclamaciones es obligatoria en municipios de gran población y puede crearse en otros por acuerdo del Pleno (mayoría absoluta) o por previsión del Reglamento Orgánico.'}},
{n:138, q:'La Comisión Especial de Sugerencias y Reclamaciones de un Ayuntamiento:', o:{a:'Está formada por representantes de todos los grupos del Pleno, de forma proporcional al número de miembros.',b:'Puede supervisar la actividad de la Administración Municipal, dando cuenta al Pleno mediante informe anual.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Comisión Especial de Sugerencias y Reclamaciones está integrada proporcionalmente y supervisa la actividad municipal, dando cuenta al Pleno con informe anual.'}},
{n:139, q:'La Comisión Especial de Sugerencias y Reclamaciones de un Ayuntamiento:', o:{a:'Tiene atribuida la defensa de los derechos de los vecinos ante la Administración Municipal.',b:'Es obligatoria en municipios de gran población y potestativa en los demás.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Comisión Especial de Sugerencias y Reclamaciones defiende los derechos de los vecinos y es obligatoria en municipios de gran población y potestativa en los demás.'}},
{n:140, q:'La Comisión Especial de Sugerencias y Reclamaciones podrá realizar informes extraordinarios:', o:{a:'Cuando lo soliciten al menos dos concejales.',b:'Cuando la gravedad o urgencia de los hechos lo aconsejen.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'b', why:{b:'La Comisión Especial de Sugerencias y Reclamaciones puede realizar informes extraordinarios cuando la gravedad o urgencia de los hechos lo aconsejen.'}},
{n:141, q:'Están obligados a colaborar con la Comisión Especial de Sugerencias y Reclamaciones:', o:{a:'Todos los órganos del gobierno municipal.',b:'Todos los órganos de la administración municipal.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'Tanto los órganos de gobierno como los de administración municipal están obligados a colaborar con la Comisión Especial de Sugerencias y Reclamaciones.'}},
{n:142, q:'De acuerdo con la Ley 8/2010 CV, para la defensa de los derechos de los vecinos y la comprobación de deficiencias en los servicios municipales, los municipios:', o:{a:'Están obligados a crear una comisión especial de sugerencias y reclamaciones.',b:'Están obligados a crear una comisión especial o un defensor o defensora de los vecinos.',c:'Pueden crear una comisión especial o un Consejo Social de la Ciudad.',d:'Pueden crear, mediante acuerdo plenario, una comisión especial de sugerencias y reclamaciones, o un defensor o defensora de los vecinos.'}, correct:'d', why:{d:'El art. 29 de la Ley 8/2010 CV establece que los municipios pueden crear, mediante acuerdo plenario, una comisión especial de sugerencias y reclamaciones o un defensor o defensora de los vecinos.'}},
{n:143, q:'De acuerdo con el art.29.2 de la Ley 8/2010 CV, el Defensor o Defensora de los Vecinos:', o:{a:'Se reunirá periódicamente con el Síndic de Greuges.',b:'Es nombrado entre vecinos de reconocido prestigio.',c:'Es nombrado para un periodo de cuatro años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 29.2 de la Ley 8/2010 CV establece que el Defensor o Defensora de los Vecinos es nombrado entre vecinos de reconocido prestigio por el Pleno Municipal.'}},
{n:144, q:'De acuerdo con la Ley 8/2010 CV, el Defensor o Defensora de los Vecinos:', o:{a:'Es designado por el Consejo Social del Municipio, o en su defecto por el Pleno Municipal.',b:'Es nombrado entre funcionarios de la respectiva Corporación Municipal.',c:'Es nombrado para un periodo de cuatro años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 8/2010 CV establece que el Defensor o Defensora de los Vecinos es designado por el Consejo Social del Municipio o, en su defecto, por el Pleno Municipal.'}},
{n:145, q:'Entre los órganos consultivos y participativos del Ayuntamiento, los Consejos Sectoriales:', o:{a:'Son órganos creados por el Pleno para canalizar la participación ciudadana en los asuntos municipales.',b:'Desarrollarán exclusivamente funciones de informe y propuesta sobre iniciativas municipales del sector correspondiente.',c:'Estarán presididos por un miembro de la Corporación, nombrado y separado libremente por el Alcalde.',d:'Todo lo reflejado en las respuestas anteriores es correcto.'}, correct:'d', why:{d:'Los Consejos Sectoriales son creados por el Pleno para la participación ciudadana, tienen funciones de informe y propuesta, y están presididos por un miembro de la Corporación nombrado por el Alcalde.'}},
{n:146, q:'La composición, organización y ámbito de actuación de los Consejos Sectoriales se establecerán:', o:{a:'Mediante acuerdo plenario.',b:'Mediante Decreto del Alcalde.',c:'Mediante acuerdo de la Junta de Gobierno Local.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La composición, organización y ámbito de los Consejos Sectoriales se establecen mediante acuerdo plenario del Ayuntamiento.'}},
{n:147, q:'De acuerdo con la Ley 8/2010 CV, respecto al Consejo Territorial de Participación, indique la respuesta correcta:', o:{a:'Su existencia es obligatoria en municipios con núcleos de población distintos del principal que agrupen más del 20% de la población municipal.',b:'Estará integrado por representantes de los grupos políticos del Ayuntamiento y presidido por el Alcalde.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Lo reflejado en las respuestas a y b es incorrecto.'}, correct:'a', why:{a:'El art. 30 de la Ley 8/2010 CV establece que el Consejo Territorial de Participación es obligatorio en municipios con núcleos de población distintos del principal que agrupen más del 20% de la población municipal.'}},
{n:148, q:'De acuerdo con la Ley 8/2010 CV, respecto al Consejo Territorial de Participación, indique la respuesta incorrecta:', o:{a:'Su creación es obligatoria en municipios de gran población y potestativa en el resto.',b:'Debe presentar un informe anual al Pleno, preferentemente en la fase inicial de elaboración de los presupuestos.',c:'Estará integrado por representantes de cada uno de los núcleos existentes, elegidos por el Ayuntamiento reglamentariamente.',d:'Su función principal es el asesoramiento y elaboración de propuestas sobre las necesidades de estos núcleos.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Consejo Territorial de Participación no es obligatorio en municipios de gran población en general, sino en aquellos con núcleos de población que superen el 20% de la población municipal.'}},
{n:149, q:'Conforme al art.131 LRBRL, el Consejo Social de la Ciudad:', o:{a:'Existirá en municipios de gran población.',b:'Tiene asignadas aquellas funciones que le asigne el Alcalde.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 131 LRBRL establece que el Consejo Social de la Ciudad existe en los municipios de gran población (más de 250.000 h. o capitales de provincia de más de 175.000 h.).'}},
{n:150, q:'El Consejo Social de la Ciudad:', o:{a:'Existe en municipios de régimen común.',b:'Está integrado por representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas.',c:'Existirá en todos los municipios.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El Consejo Social de la Ciudad está integrado por representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas del municipio.'}},
{n:151, q:'Es función que corresponde al Consejo Social de la Ciudad:', o:{a:'La emisión de informes, estudios y propuestas en materia de desarrollo económico local.',b:'La planificación estratégica de la ciudad y grandes proyectos urbanos, además de las funciones que le asigne el Pleno.',c:'Le corresponden las funciones reflejadas en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 131 LRBRL atribuye al Consejo Social de la Ciudad la emisión de informes sobre desarrollo económico, planificación estratégica y grandes proyectos urbanos, además de las funciones que le asigne el Pleno.'}},
{n:152, q:'El art.32 de la Ley 8/2010 CV establece que los municipios de más de 5.000 habitantes podrán crear un Consejo Social Municipal:', o:{a:'Cuya composición y funcionamiento se regulará en el Reglamento Orgánico Municipal.',b:'Que estará integrado por representantes de las organizaciones ciudadanas más representativas de los sectores económicos, sociales, culturales y medioambientales.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Lo reflejado en las respuestas a y b es incorrecto.'}, correct:'c', why:{c:'El art. 32 de la Ley 8/2010 CV establece ambas características del Consejo Social Municipal: composición regulada en el ROM e integración por representantes sectoriales.'}},
{n:153, q:'El Consejo Social del Municipio puede requerir informes al Defensor de los Vecinos y a la Comisión Especial de Sugerencias y Reclamaciones:', o:{a:'Sobre su actividad, siempre que lo considere oportuno.',b:'Solo sobre actividades relacionadas con sectores sociales y culturales.',c:'Sobre su actividad relacionada con el sector económico exclusivamente.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Consejo Social puede requerir informes al Defensor de los Vecinos y a la Comisión de Sugerencias y Reclamaciones sobre su actividad, siempre que lo estime oportuno.'}},
{n:154, q:'Las funciones del Consejo Social del Municipio serán determinadas:', o:{a:'Por el Alcalde.',b:'Por el Pleno en el Reglamento Orgánico Municipal.',c:'Por la Junta de Gobierno Local.',d:'Por acuerdo del propio Consejo Social Municipal.'}, correct:'b', why:{b:'Las funciones del Consejo Social del Municipio son determinadas por el Pleno en el Reglamento Orgánico Municipal.'}},
{n:155, q:'En municipios de régimen común, las Juntas de Distrito son:', o:{a:'Órganos territoriales de gestión administrativa desconcentrada.',b:'Órganos de concentración administrativa.',c:'Órganos políticos de descentralización.',d:'Órganos administrativos de descentralización.'}, correct:'a', why:{a:'Las Juntas de Distrito en municipios de régimen común son órganos territoriales de gestión administrativa desconcentrada, que acercan la administración a los distintos barrios del municipio.'}},
{n:156, q:'¿Qué otro nombre reciben las Juntas de Distrito Municipales?', o:{a:'Juntas Vecinales.',b:'Juntas Electorales.',c:'Consejos de Barrio.',d:'Consejos Escolares.'}, correct:'c', why:{c:'Las Juntas de Distrito Municipales también reciben el nombre de Consejos de Barrio, reflejando su función de representación y participación ciudadana a nivel de barrio o distrito.'}},
{n:157, q:'Las Juntas de Distrito Municipales tienen por finalidad:', o:{a:'Mejorar la gestión de los asuntos de competencia municipal.',b:'Facilitar la participación ciudadana en la gestión de los asuntos de competencia municipal y su mejora.',c:'Lo reflejado en las respuestas a y b.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Las Juntas de Distrito tienen por finalidad tanto mejorar la gestión de los asuntos municipales como facilitar la participación ciudadana en dicha gestión.'}},
{n:158, q:'Las Juntas de Distrito Municipales tendrán la organización, funciones y competencias que cada ayuntamiento les confiera, atendiendo a las características del asentamiento de la población en el término municipal:', o:{a:'Correcto, sin perjuicio de la unidad de gobierno y gestión del municipio.',b:'Incorrecto.',c:'Correcto, en todo caso.',d:'Incorrecto, dicha organización está regulada específicamente para los ayuntamientos de régimen común.'}, correct:'a', why:{a:'Las Juntas de Distrito tienen la organización que cada ayuntamiento les confiera, pero siempre sin perjuicio de la unidad de gobierno y gestión del municipio.'}},
{n:159, q:'De conformidad con el artículo 139 de la Ley 8/2010 CV, serán públicas:', o:{a:'Las sesiones de los órganos de participación.',b:'Las sesiones del resto de órganos complementarios, excepto que un acuerdo del Pleno por mayoría absoluta establezca lo contrario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 139 de la Ley 8/2010 CV establece que serán públicas las sesiones de los órganos de participación y del resto de órganos complementarios, salvo acuerdo del Pleno por mayoría absoluta en contrario.'}},
{n:160, q:'De conformidad con el artículo 139 de la Ley 8/2010 CV...', o:{a:'Se permitirá en todo caso la grabación de las sesiones de los órganos de participación por parte de particulares.',b:'A las sesiones de las comisiones municipales podrán ser convocados representantes de asociaciones vecinales o entidades de defensa de intereses sectoriales, pudiendo ser sancionados quienes desatendieren el requerimiento de comparecencia sin causa justificada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 139 de la Ley 8/2010 CV establece que se permitirá en todo caso la grabación de las sesiones de los órganos de participación por parte de particulares, como garantía de transparencia.'}},
];
